import{_ as t,o as i,c as a,a3 as s}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Static Hermes runtime","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/static-hermes-runtime/README.md"},"headers":[],"relativePath":"tools/static-hermes-runtime/README.md","filePath":"tools/static-hermes-runtime/README.md","lastUpdated":1791816043000}'),o={name:"tools/static-hermes-runtime/README.md"};function d(n,e,r,c,l,h){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="static-hermes-runtime" tabindex="-1">Static Hermes runtime <a class="header-anchor" href="#static-hermes-runtime" aria-label="Permalink to &quot;Static Hermes runtime&quot;">​</a></h1><p>This package supplies the Static Hermes backend for Pumpkin plugin components. It compiles bundled JavaScript to Hermes bytecode with <code>hermesc</code>, then links the bytecode, Hermes, the JSI shim, and generated Pumpkin/WASI bindings into a WebAssembly component. Static Hermes is the default engine; QuickJS remains available as an alternative.</p><p>Start with the <a href="./docs/">runtime documentation</a>. It links to the <a href="./docs/benchmarking">benchmarking guide</a>; this README covers toolchain setup, build profiles, compiler and linker flags, and API coverage.</p><h2 id="prepare-the-toolchain" tabindex="-1">Prepare the toolchain <a class="header-anchor" href="#prepare-the-toolchain" aria-label="Permalink to &quot;Prepare the toolchain&quot;">​</a></h2><p>Requirements: Git, CMake, and Ninja. Rust/Cargo is needed only if the configured <code>wit-bindgen</code> version is not already installed.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/static-hermes-runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare-hermes</span></span></code></pre></div><p>Preparation uses the SDK release configured in <code>wasi-sdk.json</code>, verifies its published checksum, installs the configured <code>wit-bindgen</code> version if needed, and caches the toolchain under <code>.cache/hermes/</code> by default. It checks out the source commit in <code>hermes-source.json</code>, applies the ordered patches in <code>hermes-patches/</code>, then builds host <code>hermesc</code> and the full and lean WASI 2 Hermes/JSI libraries.</p><p>The cache is reused while its source pin, patches, toolchain, and build settings match. A changed input triggers a rebuild. Preparation refreshes the managed checkout when the source pin changes and rejects local Hermes source changes outside the managed patch set. Concurrent builds share a preparation lock.</p><p>Plugin builds prepare Hermes automatically when <code>engine</code> is omitted or set to <code>&quot;static-hermes&quot;</code>. Run the command above to prewarm the toolchain or prepare it explicitly before a build. Toolchain versions are pinned in <code>toolchain-versions.json</code>; the files follow the <a href="../../schemas/upstream-release-pin.schema.json">upstream release pin schema</a>, <a href="../../schemas/upstream-git-pin.schema.json">upstream Git pin schema</a>, and <a href="../../schemas/toolchain-versions.schema.json">toolchain versions schema</a>. The package also carries the WASI 2 CMake toolchain adjustment required by Hermes. Optional paths and build settings are listed under <a href="#build-flags">Build flags</a>.</p><h2 id="engine-and-runtime-profiles" tabindex="-1">Engine and runtime profiles <a class="header-anchor" href="#engine-and-runtime-profiles" aria-label="Permalink to &quot;Engine and runtime profiles&quot;">​</a></h2><p>Omitting <code>engine</code> selects Static Hermes. Set <code>&quot;engine&quot;: &quot;quickjs&quot;</code> in the package&#39;s <code>pumpkinPlugin</code> configuration to select QuickJS.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pumpkinPlugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;entry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/plugin.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;output&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;build/plugin.wasm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;wasi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;staticHermesRuntime&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;full&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Static Hermes defaults to the lean profile. Both profiles execute precompiled Hermes bytecode; full also retains runtime source compilation, including <code>eval</code> and the <code>Function</code> constructor. Set <code>staticHermesRuntime</code> to <code>&quot;full&quot;</code> to use it. This setting requires the Static Hermes engine and cannot be combined with QuickJS.</p><p>Build the plugin with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">plugin-package-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Static Hermes builds prepare the toolchain automatically when required.</p><h2 id="production-and-development-builds" tabindex="-1">Production and development builds <a class="header-anchor" href="#production-and-development-builds" aria-label="Permalink to &quot;Production and development builds&quot;">​</a></h2><p>Production builds minify the JavaScript bundle, compile it to optimized Hermes bytecode with function names and debug information stripped, and compile the native WASI code with <code>-Oz</code>. Function/data sections allow unused code to be removed at link time. The linker strips symbols from the production component. Each production component must be no larger than 5 MiB (5,242,880 bytes).</p><p>Development builds keep the JavaScript bundle readable and retain Hermes source locations and native line tables for backtraces. Native code remains size optimized. The specific compiler and linker flags are listed below.</p><h2 id="build-flags" tabindex="-1">Build flags <a class="header-anchor" href="#build-flags" aria-label="Permalink to &quot;Build flags&quot;">​</a></h2><p>These settings cover the build tools and paths, Hermes library configuration, Hermes bytecode compilation, and WASI C/C++ compilation and linking.</p><h3 id="toolchain-paths" tabindex="-1">Toolchain paths <a class="header-anchor" href="#toolchain-paths" aria-label="Permalink to &quot;Toolchain paths&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><code>STATIC_HERMES_WASI_SDK_PATH</code></td><td>Optional WASI SDK path override. Otherwise setup reuses <code>WASI_SDK_PATH</code> or <code>WASI_SDK</code>, or discovers the matching archive and SHA-256 digest from the release configured in <code>wasi-sdk.json</code> and caches it under <code>.cache/hermes/toolchain/</code>.</td></tr><tr><td><code>STATIC_HERMES_CACHE_DIR</code></td><td>Cache root; defaults to <code>.cache/hermes/</code> at the workspace root.</td></tr><tr><td><code>STATIC_HERMES_SOURCE_DIR</code></td><td>Hermes checkout; defaults to <code>source/</code> under the cache root.</td></tr><tr><td><code>STATIC_HERMES_HOST_BUILD_DIR</code></td><td>Host build directory; defaults to <code>build-host/</code> under the cache root.</td></tr><tr><td><code>STATIC_HERMES_WASI_BUILD_DIR</code></td><td>WASI build directory; defaults to <code>build-wasip2/</code> under the cache root.</td></tr><tr><td><code>WIT_BINDGEN</code></td><td>Optional <code>wit-bindgen</code> path override. Setup reuses the configured version from <code>.cache/hermes/toolchain/</code> or <code>~/.cargo/bin/wit-bindgen</code>, then installs it if needed.</td></tr></tbody></table><h3 id="hermes-configuration" tabindex="-1">Hermes configuration <a class="header-anchor" href="#hermes-configuration" aria-label="Permalink to &quot;Hermes configuration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><code>HERMES_ENABLE_TOOLS=ON</code> on the host build</td><td>Builds <code>shermes</code>; the host executable is not included in plugins.</td></tr><tr><td>Host C/C++ Release flags <code>-Os -DNDEBUG</code></td><td>Reduces local compiler-tool size and removes assertions; it does not change plugin components.</td></tr><tr><td><code>-Wno-unused-template</code> in host Release and WASI MinSizeRel C++ flags</td><td>Suppresses unused function template warnings from upstream Hermes sources; it does not affect compiled output.</td></tr><tr><td><code>HERMES_ENABLE_TOOLS=OFF</code> on the WASI build</td><td>Excludes build tools from the runtime.</td></tr><tr><td><code>HERMES_ENABLE_NAPI=OFF</code></td><td>Excludes the Node API.</td></tr><tr><td><code>HERMES_ENABLE_TEST_SUITE=OFF</code></td><td>Skips test targets in the runtime build.</td></tr><tr><td><code>HERMES_ENABLE_DEBUGGER=OFF</code></td><td>Excludes debugger support.</td></tr><tr><td><code>HERMES_ENABLE_INTL=OFF</code></td><td>Excludes Intl APIs and their locale data.</td></tr><tr><td><code>HERMES_BUILD_SHARED_JSI=OFF</code></td><td>Keeps JSI in the static link.</td></tr><tr><td><code>HERMESVM_ALLOW_JIT=0</code></td><td>Disables the JIT, which is not used by WASI components.</td></tr><tr><td><code>HERMES_UNICODE_LITE=ON</code></td><td>Uses Hermes&#39;s reduced Unicode implementation.</td></tr><tr><td><code>HERMES_ENABLE_CORE_EXTENSIONS=OFF</code>, <code>HERMES_ENABLE_CONTRIB_EXTENSIONS=OFF</code></td><td>Omits optional JSI extensions. <code>STATIC_HERMES_ENABLE_JSI_EXTENSIONS=1</code> enables both and changes component size; measure the production component after changing it.</td></tr><tr><td><code>HERMES_ENABLE_UNICODE_REGEXP_PROPERTY_ESCAPES=ON</code></td><td>Keeps <code>\\p{...}</code> and <code>\\P{...}</code> regexp support. <code>STATIC_HERMES_ENABLE_UNICODE_REGEXP_PROPERTY_ESCAPES=0</code> removes that support and can reduce component size.</td></tr><tr><td><code>HERMES_CHECK_NATIVE_STACK=ON</code></td><td>Converts native recursion overflow into a catchable JavaScript <code>RangeError</code>; the comparison checks this for full and lean builds.</td></tr><tr><td><code>HERMES_ALLOW_BOOST_CONTEXT=0</code></td><td>Avoids Boost.Context, which is unavailable on this WASI target.</td></tr><tr><td><code>HERMESVM_GCKIND=MALLOC</code></td><td>Selects malloc-managed GC for WASI; this is not a size optimization and uses more memory.</td></tr></tbody></table><h3 id="javascript-to-c-compiler" tabindex="-1">JavaScript-to-C compiler <a class="header-anchor" href="#javascript-to-c-compiler" aria-label="Permalink to &quot;JavaScript-to-C compiler&quot;">​</a></h3><p>Production runs <code>hermesc -color -O4 -fstrip-function-names -g0 -emit-binary</code>:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>-color</code></td><td>Prints colored compiler diagnostics in build logs. The build always passes this flag, including development builds.</td></tr><tr><td><code>-Og</code></td><td>Applies Hermes optimizations intended to remain suitable for debugging; used in development.</td></tr><tr><td><code>-O4</code></td><td>Optimizes Hermes bytecode.</td></tr><tr><td><code>-fstrip-function-names</code></td><td>Removes function names from the generated string table.</td></tr><tr><td><code>-g0</code></td><td>Omits compiler debug information.</td></tr><tr><td><code>-g1</code></td><td>Keeps Hermes source locations for JavaScript backtraces without per-instruction debug data.</td></tr><tr><td><code>-emit-binary</code></td><td>Emits Hermes bytecode embedded in the component.</td></tr></tbody></table><p>Development uses <code>hermesc -Og -g1 -emit-binary</code>: the bundle stays non-minified, function names remain, and Hermes keeps source locations for JavaScript backtraces. Native C/C++ compilation uses <code>-Oz -gline-tables-only -DNDEBUG -ffunction-sections -fdata-sections</code>; this keeps native line tables and function names while minimizing code and allowing unused sections to be removed. Development components retain those line tables; the linker does not use <code>--strip-debug</code> or <code>--strip-all</code>.</p><h3 id="wasi-c-c-compilation-and-linking" tabindex="-1">WASI C/C++ compilation and linking <a class="header-anchor" href="#wasi-c-c-compilation-and-linking" aria-label="Permalink to &quot;WASI C/C++ compilation and linking&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>-Oz</code></td><td>Optimizes native WebAssembly for minimum size.</td></tr><tr><td><code>-gline-tables-only</code></td><td>Keeps native source-line mappings for backtraces without full variable/type debug data.</td></tr><tr><td><code>-DNDEBUG</code></td><td>Removes C/C++ assertions.</td></tr><tr><td><code>-ffunction-sections -fdata-sections</code></td><td>Separates code and data so unused sections can be removed.</td></tr><tr><td><code>-DSTATIC_HERMES</code></td><td>Selects the Static Hermes implementation in the native JSI shim.</td></tr><tr><td><code>-mllvm -wasm-enable-sjlj</code> with <code>-lsetjmp</code></td><td>Provides the setjmp/longjmp lowering Hermes uses for JavaScript exceptions.</td></tr><tr><td><code>-D_WASI_EMULATED_MMAN</code>, <code>-D_WASI_EMULATED_PROCESS_CLOCKS</code></td><td>Enables wasi-libc emulation for the POSIX calls Hermes needs.</td></tr><tr><td><code>-lwasi-emulated-mman</code>, <code>-lwasi-emulated-process-clocks</code></td><td>Links those wasi-libc emulation implementations.</td></tr><tr><td><code>-fwasm-exceptions</code></td><td>Keeps C++ exceptions for error handling in the JSI shim.</td></tr><tr><td><code>-w</code></td><td>Suppresses compiler diagnostics from the generated WIT C glue; used only when compiling <code>plugin.c</code>.</td></tr><tr><td><code>-mexec-model=reactor</code></td><td>Builds a reactor module whose plugin lifecycle is controlled by the component host.</td></tr><tr><td><code>-Wl,--gc-sections</code></td><td>Removes unreferenced sections from the final component.</td></tr><tr><td><code>-Wl,--strip-all</code></td><td>Removes symbol and debug tables from production components.</td></tr><tr><td><code>-Wl,--stack-first</code></td><td>Places the stack before static data so stack overflow is trapped.</td></tr><tr><td><code>-Wl,-z,stack-size=262144</code></td><td>Reserves the default 256 KiB WASI stack; <code>STATIC_HERMES_STACK_SIZE</code> changes it (a multiple of 16 bytes, at least 131072).</td></tr><tr><td><code>-lc++abi -lunwind</code></td><td>Links C++ ABI and unwinding support used by the JSI shim.</td></tr></tbody></table><p>See <a href="./docs/benchmarking">Benchmarking</a> for the comparison command, workload coverage, and report interpretation.</p><h2 id="api-and-platform-coverage" tabindex="-1">API and platform coverage <a class="header-anchor" href="#api-and-platform-coverage" aria-label="Permalink to &quot;API and platform coverage&quot;">​</a></h2><h3 id="pumpkin-api" tabindex="-1">Pumpkin API <a class="header-anchor" href="#pumpkin-api" aria-label="Permalink to &quot;Pumpkin API&quot;">​</a></h3><p><code>@pumpkin-plugins/build</code> supplies the pinned WIT directory and owns the Pumpkin API version and WASI definitions. Each build generates the component ABI and the ignored <code>generated/api-enums.generated.h</code>. It also generates event payload converters only for the WIT variants and fields used by the bundled plugin.</p><p>The native JSI shim implements part of the Pumpkin API: plugin lifecycle and metadata, command and task dispatch, event registration and dispatch, selected server/player/world methods, logging, scheduling, and Java custom payloads. Calls outside that supported subset are not available through Static Hermes.</p><p>The generated Pumpkin API facades reject host calls during <code>on_unload</code>, except <code>scheduler.cancel-task</code>, which plugins need to stop scheduled callbacks. Cancel scheduled tasks and perform local cleanup during unload; other host calls remain unavailable. This guard prevents calls from re-entering the WASM store during shutdown.</p><h3 id="wasi" tabindex="-1">WASI <a class="header-anchor" href="#wasi" aria-label="Permalink to &quot;WASI&quot;">​</a></h3><p>Static Hermes reads the WIT directory prepared by <code>@pumpkin-plugins/build</code>. It validates every operation in an imported WASI interface, including operations the plugin does not use, and emits native adapters only for operations used by the bundle. The current imported WASI 0.2.3 surface covers filesystem, HTTP, streams, clocks, TCP, UDP, and sockets. The build enables a feature-gated WIT operation when the bundle uses it.</p><p>Static Hermes development builds bypass the shared automatic Market update check. WASI 3 support is deferred.</p><p>See the <a href="https://filiphsps.github.io/pumpkin-plugins/tools/static-hermes-runtime/docs/" target="_blank" rel="noreferrer">tool guide</a> and <a href="https://filiphsps.github.io/pumpkin-plugins/api/tools/@pumpkin-plugins/static-hermes-runtime/" target="_blank" rel="noreferrer">API reference</a> on the documentation site.</p>`,41)])])}const m=t(o,[["render",d]]);export{u as __pageData,m as default};
